INSERT INTO changelog (title, body, created_at) VALUES ('Meta: витрати і ліди на одному графіку', 'Клієнт → Meta → Огляд: замість двох графіків — один. Сині стовпчики — витрати по днях (шкала зліва), зелена лінія з точками — ліди (шкала справа). Наведи на день — витрати, ліди і ціна ліда за цей день. На телефоні — окрема вузька версія з читабельними підписами.', datetime('now'));
